import React, { useState } from 'react';
import { suppliers } from '../data/mockData';
import './addProductForm.css';

function AddProductForm({ addProduct }) {
    const [id, setProductID] = useState("");
    const [productName, setProductName] = useState("");
    const [category, setCategory] = useState("");
    const [quantity, setQuantity] = useState("");
    const [unit, setUnit] = useState("");
    const [buy_price, setBuyPrice] = useState("");
    const [sell_price, setSellPrice] = useState("");
    const [supplier, setSupplier] = useState("");
    const [image, setImage] = useState("");

    // Handle Change
    const handleChange = (e) => {
        const { name, files } = e.target;
        if (name === "image") {
            setImage(files[0]); // Store the selected file in the image state
        }
    };

    // Handle the form submission
    const handleSubmit = (e) => {
        e.preventDefault();

        // Trim inputs and validate required fields
        const requiredFields = [id, productName, category, unit, supplier];
        if (requiredFields.some(field => field.trim() === "")) {
            alert("Please fill in all fields");
            return;
        }

        // Convert quantity and price to numbers
        //const parsedQuantity = quantity.trim() !== "" && !isNaN(quantity) ? parseFloat(quantity) : NaN;
        const parsedBuyPrice = buy_price.trim() !== "" && !isNaN(buy_price) ? parseFloat(buy_price) : NaN;
        const parsedSellPrice = sell_price.trim() !== "" && !isNaN(sell_price) ? parseFloat(sell_price) : NaN;

        {/*if (isNaN(parsedQuantity) || parsedQuantity <= 0) {
            alert("Please enter a valid quantity");
            return;
        }
        */}

        if (isNaN(parsedBuyPrice) || parsedBuyPrice <= 0) {
            alert("Please enter a valid price");
            return;
        }

        if (isNaN(parsedSellPrice) || parsedSellPrice <= 0) {
            alert("Please enter a valid price");
            return;
        }

        // Creating an object for the new product
        const newProduct = {
            id,
            productName,
            category,
            quantity: 0,
            unit,
            buy_price: parsedBuyPrice,
            sell_price: parsedSellPrice,
            supplier: suppliers.find(s => s.id === supplier),
            ...(image && { image }) // Add image if available
        };

        // Debugging output
        console.log("New Product:", newProduct);
        alert(`Product Added: ${JSON.stringify(newProduct, null, 2)}`);

        // Calling function onAddProduct
        addProduct(newProduct);

        // Clear the fields
        setProductID("");
        setProductName("");
        setCategory("");
        setQuantity("");
        setUnit("");
        setBuyPrice("");
        setSellPrice("");
        setSupplier("");
        setImage("");
    };

    return (
        <form onSubmit={handleSubmit}>
            <h1>Add a New Product</h1>
            <div className='formField'>
                <label>Product ID:</label>
                <input type="text" value={id} onChange={(e) => setProductID(e.target.value)} className='shortInputField' />
            </div>
            <div className='formField'>
                <label>Product Name:</label>
                <input type="text" value={productName} onChange={(e) => setProductName(e.target.value)} className='shortInputField' />
            </div>
            <div className='formField'>
                <label>Category:</label>
                <input type="text" value={category} onChange={(e) => setCategory(e.target.value)} className='shortInputField' />
            </div>
            <div className='twoFieldsHolder'>
                
                <div className='formField'>
                    <label>Buy Price:</label>
                    <input type="text" value={buy_price} onChange={(e) => setBuyPrice(e.target.value)} className='longInputField' />
                </div>

                <div className='formField'>
                    <label>Sell Price:</label>
                    <input type="text" value={sell_price} onChange={(e) => setSellPrice(e.target.value)} className='longInputField' />
                </div>
            </div>
            <div className='formField'>
                <label>Unit:</label>
                <input type="text" value={unit} onChange={(e) => setUnit(e.target.value)} className='shortInputField' />
            </div>
            <div className='formField'>
                <label>Supplier:</label>
                <select value={supplier} onChange={(e) => setSupplier(e.target.value)} className='shortInputField supplierCss'>
                    <option value="">Select Supplier</option>
                    {suppliers.map(supplier => (
                        <option key={supplier.id} value={supplier.id}>{supplier.name}</option>
                    ))}
                </select>
            </div>
            <div className='formField'>
                <label>Product Image:</label>
                <input type="file" accept="image/*" name="image" onChange={handleChange} className='longInputField' />
            </div>
            <button className='addBtn' type="submit">Add Product</button>
        </form>
    );
}

export default AddProductForm;
